node -e "
import('./src/server.js').then(m => {
  const { createApp } = m;
  const app = createApp();

  // Simulate a request
  const req = { params: { id: '123' } };
  const res = {
    json: (data) => {
      console.log(JSON.stringify(data));
      process.exit(0);
    }
  };

  app._router.stack.forEach(layer => {
    if (layer.route && layer.route.path === '/reports/:id') {
      layer.route.stack[0].handle(req, res);
    }
  });
}).catch(e => {
  console.error(e);
  process.exit(1);
});
"
